\begin{align*}
\min_{x \in \R^n} F(x) = f(x) + h(x),  %\label{eq:main_prob}
\end{align*}

\begin{assumption}\label{assumpt:convex_smooth}
 Function  $f$ is convex and $L$-smooth, function $h$ is proper, closed and convex.
\end{assumption}

\begin{assumption}\label{assumpt:bounded_below}
There exists a global minimizer of $F(x)$, $x^*$,  such that $F(x^*)=F^* > -\infty$. 
  \end{assumption}

\begin{align}
\text{prox}_h (y) = {\arg \min}_{x \in \R^n} \left\{h(x) +\frac{1}{2}\|x-y\|^2\right\},  \label{eq:prox_oper}
\end{align}

Given a  point $y\in\R^n$ and a step-size parameter $\alpha$, we define the following approximation $Q_\alpha(x, y)$ of the objective function $F$: 
\begin{align*}
Q_\alpha(x, y) = f(y) +\nabla f(y)^\top (x -y)  + \frac{1}{2\alpha}\|x-y\|^2 + h(x).
\end{align*}

The minimizer of this function with respect to $x$, which we denote by $p_\alpha (y)$ is given by the prox-operator: 
\begin{align*}
    p_\alpha (y) := \arg\min_x Q_\alpha(x, y) = \text{prox}_{\alpha h} (y - \alpha \nabla f(y)).
\end{align*}

We let $D_{\alpha}(y)$ denote the gradient mapping of $F$ \cite{Nesterov}:
\begin{align}\label{eq:gradient_mapping}
D_{\alpha}(y) := \frac{1}{\alpha}\Big(y - \text{prox}_{\alpha h}(y - \alpha\nabla{f}(y))\Big)= \frac{1}{\alpha}\Big(y - p_\alpha (y)\Big), \text{ for } \alpha > 0.
\end{align}

We also define the following approximating function based on an estimate  $g$ instead of  $\nabla f(y)$:
\begin{align*}
\tilde{Q}_\alpha(x, y) = f(y) + g^\top (x -y)  + \frac{1}{2\alpha}\|x-y\|^2 + h(x).
\end{align*}

Similarly we define
\begin{align*}
    \tilde{p}_\alpha (y) := \arg\min_x \tilde{Q}_\alpha(x, y) = \text{prox}_{\alpha h} (y - \alpha g).
\end{align*}

{\bf Stochastic first-order oracle SFO$_{\constG, p}(y,\alpha)$.}	 
{\em Given a vector $y\in \R^n$ and a step-size parameter $\alpha > 0$, the oracle computes $G(y,\xi)$, a (random) estimate of the gradient $\nabla f (y)$, such that
\begin{align}\label{eq:first_order1}
\mathbb P_{\xi} \left\{\|G(y,\xi)-\nabla f(y)\|\leq \constG \cdot  \|D_{\alpha}(y)\|   \right\}
\geq p, 
\end{align}

where $\xi$ is a random variable whose distribution may depend on $y$ and $D_{\alpha}(y)$ is defined in \eqref{eq:gradient_mapping}. The values of the constants  $\constG$ and $p$ are intrinsic to the oracle, and satisfy  {$\constG \leq \frac{1}{3}$} and $p > \frac{1}{2}$.


\begin{algorithm}[ht]
\caption{Stochastic ISTA Step Search Algorithm}
\label{alg:ista_bktr_line_search}
\begin{algorithmic}[1]
\STATE {Initialization:} 
Choose an initial point $x_0\in \mathbb{R}^d$. Set $0<\gamma<1$,  with $\alpha_1>0$. Let oracle SFO$_{\constG, p}$ be given with  {$0 \leq \constG \leq \frac{1}{3}$} and $\frac{1}{2} < p \leq 1 $.
\FOR{$k=1,2,\cdots,$}
    \STATE Set  $y_k = x_{k-1}$.
    \STATE Compute the gradient estimate $g_k=G(y_k,\xi_k)$ using the stochastic first-order oracle SFO$_{\constG, p}(y_k,\alpha_k)$.
    Compute the reference point $\tilde{p}_{\alpha_k} (y_k) =\text{prox}_{\alpha_k h} (y_k- \alpha_k g_k)$.
    \STATE Check the sufficient decrease condition $F(\tilde{p}_{\alpha_k} (y_k)) \leq \tilde{Q}_{\alpha_k}(\tilde{p}_{\alpha_k} (y_k), y_k)$.
        \STATE \hspace{1.25em}If unsuccessful: 
            \STATE \hspace{2.5em}Set $x_{k} = x_{k-1}$ and  $\alpha_{k+1} = \gamma\alpha_k$.
        \STATE \hspace{1.25em}If successful: 
            \STATE \hspace{2.5em}Set $x_k = \tilde{p}_{\alpha_k} (y_k)$ and $\alpha_{k+1} = \tfrac{\alpha_k}{\gamma}$.
\ENDFOR
\end{algorithmic}
\end{algorithm}

\textit{Filtration.}
Algorithm \ref{alg:ista_bktr_line_search} generates a stochastic process $\{Y_k, X_k, G_k, \Stepsize{k}\}$, where $G_k$ denotes the random gradient estimate computed by the oracle SFO$_{\constG, p}(Y_k,\Stepsize{k})$ at iteration $k$, $Y_k$ and $X_k$ are the random iterates and  $\Stepsize{k}$ is the random step-size  parameter. 
We use $g_k$, $y_k$, $x_k$ and $\alpha_k$  to denotes realizations of these quantities for a particular sample path. We omit explicitly stating the dependence on the sample, for brevity. 
Let $\pastone$ denote the $\sigma$-algebra generated by the random variables $G_0, \hdots, G_{k-1}$. We note that by the nature of the algorithm, distribution of $G_k$ is determined by $Y_k$, while  $X_k$,  $\Stepsize{k+1}$, and, consequently,  $Y_{k+1}$ are  deterministic conditioned on $G_k$. Therefore  process $\{G_k\}$ captures the randomness of the stochastic process $\{Y_k, X_k, G_k,  \Stepsize{k}\}$, in other words,  $\{\pastone\}_{k\ge 1}$ is a filtration. 


\textit{The hitting time $N_\epsilon$ to reach $\epsilon$ accurate solution.} 
Given a target  accuracy $\epsilon>0$, we aim to derive a bound on the expected number of iterations after which
the algorithm generates the iterate that satisfies $\{F(x_k)-F^*\leq \epsilon\}$. We denote the optimality gap $v_k = F(x_k)-F^*$ for every iteration $k$.
Let  $N_\epsilon=\min\{k=1,2, \ldots\ : F(X_k)-F^*\leq \epsilon\}$, that is $N_\epsilon$ is the first iteration for which the event $\{F(x_k)-F^*\leq \epsilon\}$ occurs.  $N_\epsilon$ is a stopping time (hitting time) with respect to the filtration $\{\mathcal{F}_k\}_{k\ge 1}$   as it is defined by the realization of $X_k$.


\begin{definition}[Successful Iteration]\label{def:success} 
Let $\iterSucc=\mathbbm{1}\{{\rm Iteration\ } k\ {\rm is\ successful } \}$.
\end{definition}

\begin{definition}[True Iteration]\label{def:good_model}
We say iteration $k$ is {\em true} if 
\begin{align*}
    \|g_k-\nabla f(y_k)\|\leq \constG  \|D_{\alpha_k}(y_k)\|, \  {\constG\leq \frac{1}{3}}.
\end{align*}

In other words, the first-order oracle delivers a sufficiently accurate estimate. 
We use an indicator variable $\iterTrue$ to indicate that iteration $k$ is true. 
\end{definition}

\begin{assumption}[Probability of True Iteration]\label{assumpt:key}
We assume that the first-order oracle  SFO$_{\constG, p}$ is implemented in Algorithm \ref{alg:ista_bktr_line_search} with  {$\constG \leq \frac{1}{3}$} and $p > \frac{1}{2}$ for every input $(y_k,\alpha_k)$. 
Then, by the properties of  the oracle and the filtration $\pastone$ we have, 
\begin{align*} 
\Prob(\iterTrue| \pastone) \ge p \text{ for all } k \geq 0.
\end{align*}
\end{assumption}

Let us define
$N_G = \sum_{k=1}^{N_\epsilon-1} \mathbbm{1}\{ \Alpha_k \ge \stepsizebar \} \cdot  \mathbbm{1}\{{\rm Iteration\ } k\ {\rm is\ true\ and \ successful} \} $ be the number of {\em good} iterations prior to the stopping time $N_\epsilon$.


\begin{assumption}\label{assumpt:ista_noise}
At every iteration $k$,  $g_k=g(y_k,\xi_k)$ computed using the stochastic first-order oracle SFO$_{\constG, p}(y_k,\alpha_k)$ satisfies  
\begin{align}\label{eq:ista_noise}
    &\EE_{\xi_k} \left[ \| (\nabla f(y_{k} )- G_{k} )\|^2 | \pastone\right] \leq \frac{1}{\alpha_{k}^2\cdot k^{2+ \beta}},
\end{align}
for some fixed $\beta>0$. 
%\trang{I thought conditioning on the filtration is essentially the same as the randomness in the oracle? since that was the only random element of the algo.} \katya{Yes, this just makes it more explicit, I think}. 
\end{assumption}

We first present that deterministic algorithm and then show how it is modified for the stochastic first-order oracles. Compared to  FISTA  in \cite{Beck-Teboulle}, FISTA-BKTR in \cite{Scheinberg-Goldfarb-Bai} uses an additional  parameter $\theta_k$, which keeps record of the changes in  $\alpha_k$  and 
utilizes the following update  
\begin{align}\label{eq:fista_step}
   (t_{new}, y) = \text{FISTAStep}(x, x^{prev}, t, \theta).
\end{align}

where FISTAStep computes 
\begin{align*}
    t_{new} &=  \frac{1 + \sqrt{1+4\theta t^2}}{2}, \text{ and }
    y = x + \frac{t-1}{t_{new}} ( x - x^{prev} ).
\end{align*}

 Here we will use the main FISTA-BKTR  scheme, however, as in the case of stochastic ISTA, the gradient estimate needs to be recomputed each time a step is attempted, even when the iteration is unsuccessful. Therefore the iteration counter gets increased on unsuccessful steps as well as successful ones and the algorithm notation needs to be updated accordingly. In particular 
we use  $x^{prev}_k$ (instead of $x_{k-1}$) to denote the iterate of the last successful iteration, that is the last iterate different from $x_k$. 
Similarly, $t_k^{next}$ denotes the value of $t_{k+1}$ that is assigned if iteration $k$ is successful, otherwise $t_{k+1}=t_k$. 
We also need to keep track of the $\alpha_k^{succ}$ - the step-size  parameter of the last successful iteration up to iteration $k$. 
On the other hand, $\alpha_k^0$ value is not used since the dynamics of the step-size  parameter are simplified - it is decreased by the factor of $\gamma$ on each unsuccessful iteration and increased proportionally on each successful one. 


\begin{algorithm}[ht]
\caption{Stochastic FISTA Step Search Algorithm}
\label{alg:fista_bktr_line_search}
\begin{algorithmic}[1]
\STATE {Initialization:} Choose an initial point $x_0\in \mathbb{R}^d$. Set $t_0 = 0$, let $x^{prev}_0 = x_0$. \nonumber\\
Set $0<\gamma<1$, $\theta_0 = \gamma$ with $\alpha_1>0$.  Let oracle SFO$_{\constG, p}$ be given with  {$0 \leq \constG \leq \frac{1}{3}$} and $\frac{1}{2} < p \leq 1 $.
\FOR{$k=1,2,\cdots,$}
    \STATE Compute $(t_k^{next}, y_k) = \text{FISTAStep}(x_{k-1}, x^{prev}_{k-1}, t_{k-1}, \theta_{k-1}) $
    \STATE Compute the gradient estimate $g_k=G(y_k,\xi_k)$ using the stochastic first-order oracle SFO$_{\constG, p}(y_k,\alpha_k)$.
    Compute the reference point $\tilde{p}_{\alpha_k} (y_k) =\text{prox}_{\alpha_k h} (y_k- \alpha_k g_k)$.
    \STATE Check sufficient decrease condition $F(\tilde{p}_{\alpha_k} (y_k)) \leq \tilde{Q}_{\alpha_k}(\tilde{p}_{\alpha_k} (y_k), y_k)$
        \STATE \hspace{1.25em}If unsuccessful: 
            \STATE \hspace{2.5em}Set $\left(x_{k},x^{prev}_{k},t_k\right) = \left(x_{k-1}, x^{prev}_{k-1}, t_{k-1}\right)$, then set $\alpha_{k+1} = \gamma\alpha_k$, %$\alpha^{succ}_{k}=\alpha^{succ}_{k-1}$ 
            and $\theta_{k} = \tfrac{\theta_{k-1}}{\gamma}$.
        \STATE \hspace{1.25em}If successful: 
            \STATE \hspace{2.5em}Set $\left(x_k, x^{prev}_{k},t_k\right) = \left(\tilde{p}_{\alpha_k} (y_k), x_{k-1}, t_k^{next}\right)$,
    then set $\alpha_{k+1} = \tfrac{\alpha_k}{\gamma},$ %$\alpha^{succ}_{k}=\alpha_k$ 
    and $\theta_{k} = \gamma$.
\ENDFOR
\end{algorithmic}
\end{algorithm}

Similar to Algorithm \ref{alg:ista_bktr_line_search}, 
Algorithm \ref{alg:fista_bktr_line_search} generates a stochastic process $\{Y_k, X_k, G_k, \Stepsize{k}, T_k\}$ with realizations $\{y_k, x_k, g_k, \alpha_k, t_k\}$. 


\begin{align}\label{eq:define_m}
    m_k = 2\alpha^{succ}_{k} t_{k}^2v_{k} +\norm{u_k }^2,
\end{align}

where $v_k =  F(x_k) - F^* $ and $u_k = (t_{k}-1)x^{prev}_{k} + x^* - t_k x_k $. 


\begin{assumption}\label{assumpt:fista_noise}
At every iteration $k$,  $g_k=g(y_k,\xi_k)$ computed using the stochastic first-order oracle SFO$_{\constG, p}(y_k,\alpha_k)$ satisfies 
\begin{align}\label{eq:fista_noise}
&\EE_{\xi_k} \left[ \| (\nabla f(y_{k} )- G_{k} )\|^2 | \pastone\right] \leq \frac{1}{\alpha_{k}^2t_{k}^2\cdot k^{2+ \beta}},
\end{align}
for some fixed $\beta>0$.
\end{assumption}

