\begin{theorem}\label{th:final_results}
Under Assumptions \ref{assumpt:convex_smooth}, \ref{assumpt:bounded_below}, \ref{assumpt:key} and Assumption \ref{assumpt:fista_noise} the number of iterations $N_\epsilon$ to reach an $\epsilon$-accurate solution satisfies the following bound: 
\begin{align*}
\EE (N_\epsilon) \leq \frac{2p}{(2p-1)^2}\left ( \left(
 \frac{8 \left [3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \frac{4(\beta + 2)^2}{\beta^2} + \frac{8(\beta+2)}{\beta+1}  
 \right]}{\stepsizebar\epsilon} \right)^{\frac{1}{2}}+ \log_\gamma\left(\frac{\stepsizebar}{\alpha_1}\right)\right) +1,
\end{align*}
where  $\stepsizebar $ is defined in Lemma \ref{lem:good_est_good_model_successful}.
\end{theorem}

