proof.raw_tex:
\begin{lemma}
\label{lem:good_est_good_model_successful} 
Suppose that iteration $k$ is true, i.e. 
\begin{align*}
    \|g_k-\nabla f(y_k)\|\leq \constG  \|D_{\alpha_k}(y_k)\|,
\end{align*}
with  {$\constG \leq \frac{1}{3}$} and $D_{\alpha_k}(y_k)$ is the gradient mapping of $F$ at $y_k$. If 
\begin{align*}
\stepsize{k}{} \le \stepsizebar := \frac{1}{L}\left( 1 - \frac{2\constG}{1-\constG}\right) ,
\end{align*}
then the $k$-th step is successful. 

\end{lemma}

\begin{proof}


From the $L$-smoothness of $f$ we have
\begin{align*}
    f(\tilde{p}_{\alpha_k} (y_k))  &\le f(y_k) + \nabla f(y_k)^\top(\tilde{p}_{\alpha_k} (y_k) - y_k) + \frac{L}{2}\norm{\tilde{p}_{\alpha_k} (y_k) - y_k}^2 \nonumber\\
     &= f(y_k) +  g_k^\top (\tilde{p}_{\alpha_k} (y_k) - y_k) + [\nabla f(y_k)-g_k]^\top (\tilde{p}_{\alpha_k} (y_k) - y_k)  \nonumber\\
     &\quad+ \frac{1}{2\alpha_k} \norm{\tilde{p}_{\alpha_k} (y_k) - y_k}^2  + \left(\frac{L}{2}- \frac{1}{2\alpha_k}\right)\norm{\tilde{p}_{\alpha_k} (y_k) - y_k}^2 .
\end{align*}
Adding the non-smooth term $ h(\tilde{p}_{\alpha_k} (y_k))$ we have
\begin{align*}
    &F (\tilde{p}_{\alpha_k} (y_k))  \nonumber\\
     &\le f(y_k) +  g_k^\top (\tilde{p}_{\alpha_k} (y_k) - y_k) + \frac{1}{2\alpha_k} \norm{\tilde{p}_{\alpha_k} (y_k) - y_k}^2 + h(\tilde{p}_{\alpha_k} (y_k))  \nonumber\\
     &\quad + [\nabla f(y_k)-g_k]^\top (\tilde{p}_{\alpha_k} (y_k) - y_k) + \left(\frac{L}{2}- \frac{1}{2\alpha_k}\right)\norm{\tilde{p}_{\alpha_k} (y_k) - y_k}^2 
     \nonumber\\
     &= \tilde{Q}_{\alpha_k}(\tilde{p}_{\alpha_k} (y_k), y_k) + [\nabla f(y_k)-g_k]^\top (\tilde{p}_{\alpha_k} (y_k) - y_k) + \left(\frac{L}{2}- \frac{1}{2\alpha_k}\right)\norm{\tilde{p}_{\alpha_k} (y_k) - y_k}^2 .
\end{align*}
To show that the iteration is successful i.e. $F(\tilde{p}_{\alpha_k} (y_k)) \leq \tilde{Q}_{\alpha_k}(\tilde{p}_{\alpha_k} (y_k), y_k)$
we need to prove that 
\begin{align}\label{eq:02}
    [\nabla f(y_k)-g_k]^\top (\tilde{p}_{\alpha_k} (y_k) - y_k) \leq \left(\frac{1}{2\alpha_k} - \frac{L}{2}\right)\norm{\tilde{p}_{\alpha_k} (y_k) - y_k}^2 .
\end{align}
Note that the right hand side is non-negative since $\alpha_k \leq \frac{1}{L}$. 
Our definition of the true iteration leads to 
\begin{align}\label{eq:01}
    \|g_k-\nabla f(y_k)\|
    &\leq \constG \left \|\frac{1}{\alpha_k}\Big(y_k - p_{\alpha_k} (y_k)\Big)\right\|\nonumber  \\
    &\leq  \frac{\constG}{\alpha_k} \left \|y_k - \tilde{p}_{\alpha_k} (y_k)\right\| + \frac{\constG}{\alpha_k} \left \|\tilde{p}_{\alpha_k} (y_k) - p_{\alpha_k} (y_k)\right\|\nonumber  \\
    &=  \frac{\constG}{\alpha_k} \left \|y_k - \tilde{p}_{\alpha_k} (y_k)\right\| + \frac{\constG}{\alpha_k} \norm{\alpha_k\nabla f(y_k)-\alpha_k g_k },
\end{align}
where the last inequality follows  from the nonexpansiveness of the prox-operator $\text{prox}_{\alpha h}$ for  proper, closed, and convex $h(x)$, i.e.,
\begin{align*}
    \|\text{prox}_{\alpha h}(z_1) - \text{prox}_{\alpha h}(z_2)\| \leq \|z_1 - z_2\| \text{ for all } z_1, z_2\in\R^d.
\end{align*}
The bound \eqref{eq:01} is equivalent to
\begin{align*}
    (1-\constG)\norm{\nabla f(y_k)-g_k} \leq  \frac{\constG}{\alpha_k} \left \|y_k - \tilde{p}_{\alpha_k} (y_k)\right\|.
\end{align*}
Therefore we show \eqref{eq:02} by
\begin{align*}
    \norm{\nabla f(y_k)-g_k} &\leq  \frac{\constG}{1-\constG} \frac{1}{\alpha_k} \left \|y_k - \tilde{p}_{\alpha_k} (y_k)\right\|  \nonumber\\
    &\leq \left( \frac{1- \alpha_k  L}{2}\right)\frac{1}{\alpha_k} \left \|y_k - \tilde{p}_{\alpha_k} (y_k)\right\| = \left( \frac{1}{2\alpha_k} - \frac{L}{2}\right)\left \|y_k - \tilde{p}_{\alpha_k} (y_k)\right\|,
\end{align*}
where we use the condition that 
\begin{align*}
    \frac{\constG}{1-\constG} \leq \frac{1- \alpha_k  L}{2},
\end{align*}
which is the consequence of the small step-size parameter: 
\begin{align*}
    \alpha_k  \leq \frac{1}{L}\left( 1 - \frac{2\constG}{1-\constG}\right).
\end{align*}

~\qed \end{proof}

\begin{theorem}[Bounding $\EE (N_\epsilon)$ based on $\EE(N_G)$]\label{th:framework}
Let $\stepsizebar$ be the value stated in Lemma \ref{lem:good_est_good_model_successful}.
 Under Assumption \ref{assumpt:key} we have 
\begin{align*}
\EE (N_\epsilon -1) \leq \frac{2p}{(2p-1)^2}\left (2\EE(N_G)+ \log_\gamma\left(\frac{\stepsizebar}{\alpha_1}\right)\right).
\end{align*}
\end{theorem}

\begin{proof}
By the update rule of $\alpha_k$ in Algorithm \ref{alg:ista_bktr_line_search}, the stochastic process $\{\Alpha_k\}_{k\geq 1}$ follows: 
\begin{align*}
\Alpha_{1}&= \alpha_1, \quad 
\Alpha_{k+1}=\left \{ \begin{array}{ll} 
\gamma^{-1} \Alpha_k & {\rm if\  }  \iterSucc=1,  \\
 \gamma \Alpha_k &   {\rm if\  }  \iterSucc=0 .
\end{array}\right . 
\end{align*}

Let us now define the following indicator random variables: %two indicator random variables, in addition to $\iterTrue$ defined earlier,
\begin{align*}
\iterLarge=\mathbbm{1}\{ \Alpha_k >\stepsizebar\}, \\
\iterLargebar= \mathbbm{1}\{ \Alpha_k \geq \stepsizebar\}.
\end{align*}
Clearly 
\begin{align*}
\EE (N_\epsilon-1) = \EE\left (\sum_{k=1}^{N_\epsilon-1} \iterLarge\right ) + \EE \left (\sum_{k=1}^{N_\epsilon-1} (1-\iterLarge)\right ).
\end{align*}

From Lemma 2.3 in \cite{Cartis-Scheinberg}, under Assumption \ref{assumpt:key} and using the fact that all true iterations are successful when $\alpha_k \le \stepsizebar$, we have: 
\begin{align*}
\EE\left (\sum_{k=1}^{N_\epsilon-1} (1-\iterLarge)\right)\leq \frac{1}{2p}\EE(N_\epsilon -1 ).
\end{align*}


We define 
\begin{itemize}
\item $N_{FS}=\sum_{k=1}^{N_\epsilon-1} \iterLargebar (1-\iterTrue)\iterSucc$, which is the number of false successful iterations with $\Alpha_k\geq \stepsizebar$.
\item $N_F=\sum_{k=1}^{N_\epsilon-1} \iterLargebar (1-\iterTrue)$, which is the number of false  iterations with $\Alpha_k\geq \stepsizebar$.
\item $N_G=\sum_{k=1}^{N_\epsilon-1} \iterLargebar \iterTrue \iterSucc$, which is the number of true successful iterations with $\Alpha_k\geq \stepsizebar$.
\item $N_T=\sum_{k=1}^{N_\epsilon-1} \iterLargebar \iterTrue$, which is the number of true iterations with $\Alpha_k\geq \stepsizebar$.
% \item $N_{TU}=\sum_{k=1}^{N_\epsilon-1} \iterLarge \iterTrue (1-\iterSucc)$, which is the number of true unsuccessful iterations with $\Alpha_k> \stepsizebar$.
\item $N_U=\sum_{k=1}^{N_\epsilon-1} \iterLarge  (1-\iterSucc)$, which is the number of unsuccessful iterations with $\Alpha_k> \stepsizebar$.
\end{itemize}

From equations (11) and (12) of Lemma 2.7 in \cite{Cartis-Scheinberg} we have
\begin{align}\label{eq:binom}
\EE(N_{FS})\leq \EE(N_{F})\leq\frac {1-p}{p}[\EE(N_G)+\EE(N_U)],
\end{align}
and
\begin{align}\label{eq:boundM3}
\EE(N_U)\leq \EE(N_{FS})+\EE(N_G) + \log_\gamma(\stepsizebar/\alpha_1).
\end{align}
Plugging \eqref{eq:boundM3} into  \eqref{eq:binom}
we obtain
\begin{align*}
\EE(N_{FS})\leq \frac {1-p}{p}\left[\EE(N_{FS})+2\EE(N_G) + \log_\gamma(\stepsizebar/\alpha_1)\right],
\end{align*}
and, hence,
\begin{align*}
\frac {2p-1}{p}\EE(N_{FS})\leq \frac {1-p}{p}\left[ 2\EE(N_G) + \log_\gamma\left(\frac{\stepsizebar}{\alpha_1}\right)\right].
\end{align*}
This finally implies 
\begin{align}\label{eq:boundN1}
\EE(N_{FS})\leq \frac {1-p}{2p-1}\left [2\EE(N_G)+ \log_\gamma\left(\frac{\stepsizebar}{\alpha_1}\right)\right ].
\end{align}
Now we can bound the expected total  number of  iterations when $\alpha_k>\stepsizebar$, using %\eqref{eq:N2}, 
\eqref{eq:boundM3} and \eqref{eq:boundN1}  
and adding the terms to obtain the result of the lemma, namely,
\begin{align*}
\EE(N_F+N_T)&\leq \EE(N_F+N_U+N_G)\leq \frac{1}{p}\EE(N_U+N_G)\nonumber\\
&\leq \frac{1}{2p-1}\left (2\EE(N_G)+ \log_\gamma\left(\frac{\stepsizebar}{\alpha_1}\right)\right).
\end{align*}
Next, from Lemma 2.7 in \cite{Cartis-Scheinberg},\footnote{Final statement of the Lemma 2.7 in \cite{Cartis-Scheinberg}  replaces $\EE(N_G)$ with its bound, but here we
are yet to derive such a  bound, therefore we explicitly use $\EE(N_G)$.}
\begin{align*}
\EE\left (\sum_{k=1}^{N_\epsilon-1}\iterLarge \right )\leq \frac{1}{2p-1}\left (2\EE(N_G)+ \log_\gamma\left(\frac{\stepsizebar}{\alpha_1}\right)\right). 
\end{align*}
Hence, using the two previous results we have 
\begin{align*}
\EE (N_\epsilon -1)\leq \frac{1}{2p} \EE (N_\epsilon -1) +   \frac{1}{2p-1} \left (2\EE(N_G)+ \log_\gamma\left(\frac{\stepsizebar}{\alpha_1}\right)\right).
\end{align*}
The result of the theorem follows. 
~\qed \end{proof}

\begin{lemma}[Bounds for a successful step]\label{lem:successful_step_bound1}
If $k$ is a successful iteration then we have:
\begin{align*}
\|x_{k} - x^*\|^2 - \|x_{k-1} - x^* \|^2 \leq  - 2\alpha_k (F(x_k) - F(x^*) )  + \lambda_k \cdot \|x_{k-1} -x^*\|,
\end{align*}
where $\lambda_k = \| 2\alpha_k (\nabla f(x_{k-1})-g_k) \| $.
\end{lemma}

\begin{proof}
Since iteration $k$ is successful,  the sufficient decrease condition holds: 
\begin{align*}
    F(\tilde{p}_{\alpha_k} (x_{k-1})) &\leq \tilde{Q}_{\alpha_k}(\tilde{p}_{\alpha_k} (x_{k-1}), x_{k-1}) \nonumber\\
    &= f(x_{k-1}) +(x_k -x_{k-1})^\top g_k + \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2 + h(x_k).
\end{align*}
By the  convexity of $f$ and $h$, applied at $x_{k-1}$ and $x_k$ respectively, for any $x$,  
 \begin{align*}
f(x) &\geq f(x_{k-1}) + \nabla f(x_{k-1})^\top (x-x_{k-1}),
\nonumber\\
h(x) &\geq h(x_k) + \gamma(x_{k-1})^\top (x-x_k),
\end{align*}
where the second bound holds for every subgradient $\gamma(x_{k-1})$ of $h$ at $x_{k}$. 
Summing those inequality we have 
\begin{align*}
f(x) +h(x) \geq f(x_{k-1}) + \nabla f(x_{k-1})^\top (x-x_{k-1})+ h(x_k) + \gamma(x_{k-1})^\top (x-x_k).
\end{align*}
Combining this with the sufficient decrease condition we get: 
\begin{align*}
    &F(x) - F(x_k) \nonumber\\&\geq \nabla f(x_{k-1})^\top (x-x_{k-1}) + \gamma(x_{k-1})^\top (x-x_k) - (x_k -x_{k-1})^\top g_k - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + (\gamma(x_{k-1})+g_k)^\top (x-x_k) - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2.
\end{align*}
Using the fact that $x_k = \tilde{p}_{\alpha_k} (x_{k-1}) =\arg\min_x \tilde{Q}_{\alpha_k}(x, x_{k-1})$, we get that $ x_{k-1} - x_k= \alpha_k[\gamma(x_{k-1})+g_k]$ for some subgradient $\gamma(x_{k-1})$ of $h$ at $x_{k}$. Therefore
\begin{align*}
    &F(x) - F(x_k) \nonumber\\
    &\geq (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{\alpha_k}(x_{k-1} - x_k)^\top (x-x_k) - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{\alpha_k}(x_{k-1} - x_k)^\top (x-x_{k-1} + x_{k-1} -x_k) \nonumber\\
    & \quad - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{\alpha_k}(x_{k-1} - x_k)^\top (x-x_{k-1}) + \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{2\alpha_k} \left( \|x-x_k \|^2-\|x-x_{k-1} \|^2\right),
\end{align*}
and we get the bound for $x=x^*$: 
\begin{align*}
    &2\alpha_k (F(x_k) - F(x^*) ) - 2\alpha_k (\nabla f(x_{k-1})-g_k) ^\top (x_{k-1} -x^*)
    \leq \|x_{k-1} - x^*\|^2 - \|x_k - x^* \|^2.
\end{align*}
Rearranging the terms, we get the statement of Lemma \ref{lem:successful_step_bound1}:
\begin{align*}
    \|x_k - x^* \|^2 - \|x_{k-1} - x^*\|^2 &\leq -2\alpha_k (F(x_k) - F(x^*) ) + 2\alpha_k (\nabla f(x_{k-1})-g_k) ^\top (x_{k-1} -x^*)\nonumber\\
    &\leq -2\alpha_k (F(x_k) - F(x^*) ) + \lambda_k \cdot\|x_{k-1} -x^*\|,
\end{align*}
where $\lambda_k = \|2\alpha_k (\nabla f(x_{k-1})-g_k)\|$.

~\qed \end{proof}

\begin{lemma}\label{lem:after_K1}
    After $K$ iterations of the algorithm, the following bound holds: 
\begin{align*}
\sum_{k\in S, k \leq K} 2\alpha_k (F(x_k) - F(x^*) )
    &\leq 2\|x_0 - x^* \|^2 + \sum_{k=1}^K \lambda_k \cdot \left( \sum_{i=1}^{k-1} \lambda_i \right)+ 2\sum_{k=1}^K \lambda_k^2,
\end{align*}
where $S$ is the set of successful iterations.
\end{lemma}

\begin{proof}
For every $K$, from Lemma \ref{lem:successful_step_bound1} we have
\begin{align*}
    \|x_K - x^* \|^2 - \|x_0 - x^* \|^2 
    &= \sum_{k=1}^{K} \left(\|x_{k} - x^* \|^2 -\|x_{k-1} - x^* \|^2 \right) \nonumber\\
    &\leq \sum_{k\in S, k \leq K} \left[\lambda_k \cdot \|x_{k-1} -x^*\| - 2\alpha_k (F(x_k) - F(x^*) ) \right],
\end{align*}
where $S$ is the set of successful iterations. 
Hence we arrive at our key bound
\begin{align}\label{eq:thm_key1}
    &\|x_K - x^* \|^2 - \|x_0 - x^* \|^2 + \sum_{k\in S, k \leq K} 2\alpha_k (F(x_k) - F(x^*) )\leq  \sum_{k=1}^K \lambda_k  \cdot \| x_{k-1} -x^* \|.
\end{align}
Now we follow a similar argument as \cite{Schmidt-Roux-Bach} with two steps. First, we use the key bound \eqref{eq:thm_key1} to bound the distance to optimal point $u_{k-1} = \| x_{k-1} -x^* \|$ in terms of the initial distance $u_{0} = \| x_{0} -x^* \|$ and the noise terms $\lambda_k$. Then we use this bound on $\| x_{k-1} -x^* \|$ to substitute into the last sum of the key bound \eqref{eq:thm_key1} and obtain the final derivation in terms of the noise $\lambda_k$.\\
Dropping the positive term $\sum_{k\in S, k \leq K} 2\alpha_k (F(x_k) - F(x^*) )$ we get
\begin{align*}
    \|x_K - x^* \|^2 
    &\leq \|x_0 - x^* \|^2 + \sum_{k=1}^K \lambda_k \cdot \| x_{k-1} -x^* \| \nonumber\\
    &= \|x_0 - x^* \|^2 + \lambda_1 \cdot \| x_{0} -x^* \| + \sum_{k=1}^K \lambda_{k+1} \cdot\| x_{k} -x^* \|.
\end{align*}
Letting $u_k = \| x_{k} -x^* \|$, this is equivalent to 
\begin{align*}
    u_K^2 = \|x_K - x^* \|^2  \leq Z + \sum_{k=1}^K\lambda_{k+1} u_k.
\end{align*}
where $Z = \|x_0 - x^* \|^2 + \lambda_1 \cdot \| x_{0} -x^* \| = u_0^2 + \lambda_1 u_0$. %\katya{there seems to be incorrect switching between $k$ and $K$ in a few places here} 
Using this inequality and applying Lemma 1 in \cite{Schmidt-Roux-Bach} for the non-negative sequence $\{u_K\}$ have
\begin{align*}
     u_{k} \leq \frac{1}{2} \sum_{i=1}^{k} \lambda_{i+1} + \left(Z + \left(\frac{1}{2} \sum_{i=1}^{k} \lambda_{i+1} \right)^2\right)^{1/2}
    \leq  \sum_{i=1}^{k} \lambda_{i+1} + Z^{1/2}  \leq  \sum_{i=1}^{k+1} \lambda_{i} + u_0 ,
\end{align*}
where the last line follows from the fact that $Z^{1/2} = \left(u_0^2 + \lambda_1  \cdot u_0 \right)^{1/2} \leq u_0 + \lambda_1.$
\\
Putting the bound for $u_k$ into the key bound \eqref{eq:thm_key1} we have
\allowdisplaybreaks
\begin{align*}
    &\|x_K - x^* \|^2 - \|x_0 - x^* \|^2 + \sum_{k\in S, k \leq K} 2\alpha_k (F(x_k) - F(x^*) )\nonumber\\
    &\leq \sum_{k=1}^K \lambda_k \cdot \| x_{k-1} -x^* \|\leq \sum_{k=1}^K \lambda_k \cdot \left( \sum_{i=1}^{k} \lambda_i + \|x_0 - x^* \|\right)\nonumber\\
    &= \sum_{k=1}^K \lambda_k \cdot \left( \sum_{i=1}^{k} \lambda_i \right) + \|x_0 - x^* \| \cdot \sum_{k=1}^K \lambda_k\nonumber\\
    &\leq  \sum_{k=1}^K \lambda_k \cdot \left( \sum_{i=1}^{k-1} \lambda_i \right)+ \sum_{k=1}^K \lambda_k^2 + \|x_0 - x^* \|^2 + \sum_{k=1}^K \lambda_k^2 \nonumber\\
    &= \|x_0 - x^* \|^2 + \sum_{k=1}^K \lambda_k \cdot \left( \sum_{i=1}^{k-1} \lambda_i \right)+ 2\sum_{k=1}^K \lambda_k^2,
\end{align*}
and the statement of Lemma \ref{lem:after_K1} follows. 
~\qed
\end{proof}

\begin{theorem}[Upper bound of the number of good steps]\label{th:bound_expectation_N_TS1} Under Assumption \ref{assumpt:convex_smooth}, \ref{assumpt:bounded_below}  ,
and  Assumption \ref{assumpt:ista_noise}, we have 
 \begin{align*}
\EE [N_G] 
\leq \frac{1}{2\stepsizebar\epsilon} \left [2\|x_0 - x^* \|^2 + \frac{4(\beta + 2)^2}{\beta^2} + \frac{8(\beta+2)}{\beta+1} 
 \right]. 
\end{align*}

\end{theorem}

\begin{proof}
We recall the definition of the noise term $\lambda_k =  \|2\alpha_{k} (\nabla f(y_{k} )- g_{k} )\| $. Let $\Lambda_k =  \|2\Alpha_{k} (\nabla f(Y_{k} )- G_{k} )\| $, thus $\Lambda_k$ is a random variable with realizations  $\lambda_k$. 
Since the statement of Lemma \ref{lem:after_K1} holds for every realizations of Algorithm \ref{alg:ista_bktr_line_search}, for $K = N_\epsilon -1$ we have:  
\begin{align*}
\sum_{k\in S, k \leq N_\epsilon -1} 2\Alpha_k (F(X_k) - F(x^*) )
    &\leq 2\|x_0 - x^* \|^2 + \sum_{k=1}^{N_\epsilon -1} \Lambda_k \cdot \left( \sum_{i=1}^{k-1} \Lambda_i \right)+ 2\sum_{k=1}^{N_\epsilon -1} \Lambda_k^2,
\end{align*}
where $S$ is the set of successful iterations.
Recall that the stopping time $N_\epsilon = \min\{k = 1,2, \ldots\,:  F(X_k) - F^*  \leq \epsilon\}$. Hence for every $k \leq N_\epsilon-1$, we have that $ F(X_k) - F^*> \epsilon$ and
\begin{align*}
    \epsilon \cdot \sum_{k\in S, k \leq N_\epsilon -1} 2\Alpha_k  &<  \sum_{k\in S, k \leq N_\epsilon -1} 2\Alpha_k (F(X_k) - F(x^*) )\nonumber\\
    &\leq 2\|x_0 - x^* \|^2 + \sum_{k=1}^{N_\epsilon} \Lambda_k \cdot \left( \sum_{i=1}^{k-1} \Lambda_i \right)+ 2\sum_{k=1}^{N_\epsilon} \Lambda_k^2.
\end{align*}
Let $\mathcal{N}_G$ be the set of \textit{good} iterations  i.e. true and successful iterations $k$ with $\alpha_k\geq \stepsizebar, k \leq N_\epsilon -1 $, then $N_G$ is the cardinality of that set. We have 
\begin{align*} 
\sum_{k\in S, k \leq N_\epsilon -1} 2\Alpha_k \geq\sum_{k\in \mathcal{N}_G, k \le N_\epsilon -1 }  2\Alpha_k \geq N_G \cdot 2\stepsizebar = 2 N_G \stepsizebar.
\end{align*}
Therefore 
\begin{align*}
    2 N_G \stepsizebar \cdot \epsilon  
    &\leq 2\|x_0 - x^* \|^2 + \sum_{k=1}^{N_\epsilon} \Lambda_k \cdot \left( \sum_{i=1}^{k-1} \Lambda_i \right)+ 2\sum_{k=1}^{N_\epsilon} \Lambda_k^2,
\end{align*}
and 
\begin{align*}
    N_G   
    &\leq \frac{2\|x_0 - x^* \|^2 + \sum_{k=1}^{N_\epsilon} \Lambda_k \cdot \left( \sum_{i=1}^{k-1} \Lambda_i \right)+ 2\sum_{k=1}^{N_\epsilon} \Lambda_k^2}{2 \stepsizebar \epsilon}.
\end{align*}
Taking expectation we have %\trang{notations here}
\begin{align}\label{eq:bound1}
\EE [N_G ] 
 &\leq \frac{1}{2\stepsizebar\epsilon} \left [2\|x_0 - x^* \|^2 
+ \EE \left[ \sum_{k=1}^{N_\epsilon} \Lambda_{k} \cdot \left(\sum_{i=1}^{k-1} \Lambda_{i} \right)  \right] + 2\EE \left[\sum_{k=1}^{N_\epsilon}  \Lambda_{k} ^2  \right] 
 \right]  .
\end{align}
In order to bound \eqref{eq:bound1}, we derive the expected values of $\Lambda_k^2$, $\Lambda_k$ and $\Lambda_k \Lambda_i$ for $1\leq i, k \leq N_\epsilon$
using Assumption \ref{assumpt:ista_noise}. From \eqref{eq:ista_noise} we have: 
\begin{align}\label{eq:mu_k_squared1}
    \EE \left[\Lambda_{k}^2| \pastone\right] = \EE \left[4\alpha_{k}^2 \| (\nabla f(y_{k} )- G_{k} )\|^2 | \pastone\right] \leq \frac{4}{k^{2+ \beta}},
\end{align}
which leads to 
\begin{align*}
    \left(\EE \left[\Lambda_{k}| \pastone\right]\right)^2 \leq \EE \left[\Lambda_{k}^2| \pastone\right] \leq \frac{4}{k^{2+ \beta}}.
\end{align*}
Therefore we have the bound for $\EE \left[\Lambda_{k}| \pastone\right]$: 
\begin{align}\label{eq:mu_k1}
    \EE \left[\Lambda_{k}| \pastone\right] \leq \frac{2}{k^{1+ 0.5\beta}}.
\end{align} 
Taking the total expectation of \eqref{eq:mu_k_squared1} and \eqref{eq:mu_k1} we have 
\begin{align*}
    \EE \left[\Lambda_{k}^2\right] \leq \frac{4}{k^{2+ \beta}} \text{ and } \EE \left[\Lambda_{k}\right] \leq \frac{2}{k^{1+ 0.5\beta}}.
\end{align*} 
Now we consider the quantity $\EE \left[\Lambda_{k}\Lambda_{i}| \pastone\right] $ where $i< k $. 
From the definition of  the filtration $\pastone$ and $\Lambda_{i}$,  {we have that} $\Lambda_i \in \pastone$ for all $i < k$. Therefore by the rules of conditional probability
\begin{align*}
    \EE \left[\Lambda_{k}\Lambda_{i}| \pastone\right] =  \EE \left[\Lambda_{k}| \pastone\right] \Lambda_i .
\end{align*}
Hence we can bound the expect value of $\Lambda_{k}\Lambda_{i}$ as follows: 
\begin{align*}
    \EE \left[\Lambda_{k}\Lambda_{i}  \right] 
    &=\EE \left[\EE \left[\Lambda_{k}\Lambda_{i}| \pastone \right] \right]  =\EE \left[\EE \left[\Lambda_{k}| \pastone\right] \Lambda_i  \right] 
    \nonumber\\ \nonumber
    &  {\leq} \EE \left[\EE \left[\frac{2}{k^{1+ 0.5\beta}} \Lambda_i  \right]  \right]   = \frac{2}{k^{1+ 0.5\beta}} \EE \left[\EE \left[ \Lambda_i | \pastonei \right]  \right]
    \nonumber\\ \nonumber
    &  {\leq} \frac{2}{k^{1+ 0.5\beta}} \frac{2}{i^{1+ 0.5\beta}} .
\end{align*}
Since $N_\epsilon$ is a hitting time and the random variables $\Lambda_k^2$, $\Lambda_{k}\Lambda_{i}$ have finite means and are summable (over $\{k = 1,2, \ldots\}$ and over $\{i, k = 1,2,\ldots\}$ respectively), from the general Wald's identity  {\cite{Wald}} we have: 
\begin{align*}
\EE \left[\sum_{k=1}^{N_\epsilon} \Lambda_{k} ^2  \right] &= \EE \left(\sum_{k=1}^{N_\epsilon}\EE \left[  \Lambda_{k} ^2  \right]  \right)\nonumber\\
\EE \left[ \sum_{k=1}^{N_\epsilon}\Lambda_{k} \cdot \left(\sum_{i=1}^{k-1} \Lambda_{i} \right)  \right] &= \EE \left(\sum_{k=1}^{N_\epsilon}\sum_{i=1}^{k-1}\EE \left[  \Lambda_{k} \Lambda_{i}  \right] \right) .
\end{align*}
Applying the previous total expected value bounds in these inequality we have: 
 \begin{align*}
\EE \left[\sum_{k=1}^{N_\epsilon} \Lambda_{k} ^2  \right] & = \EE \left(\sum_{k=1}^{N_\epsilon}\EE \left[  \Lambda_{k} ^2  \right]  \right)
\leq 4\EE \left(\sum_{k=1}^{N_\epsilon}\frac{1}{k^{2+ \beta}}\right) \leq  \frac{4(\beta +2)}{\beta+1}\nonumber\\
 \EE \left[ \sum_{k=1}^{N_\epsilon}\Lambda_{k} \left(\sum_{i=1}^{k-1} \Lambda_{i} \right)  \right] &= \EE \left(\sum_{k=1}^{N_\epsilon}\sum_{i=1}^{k-1}\EE \left[  \Lambda_{k} \Lambda_{i}  \right] \right) \leq 4\EE \left(\sum_{k=1}^{N_\epsilon}\frac{1}{k^{1+ 0.5\beta}} \sum_{i=1}^{k-1} \frac{1}{i^{1+ 0.5\beta}}\right) \leq \frac{4(\beta + 2)}{\beta},
\end{align*}
where the last computations follows from 
\begin{align*}
    &\sum_{k=1}^{N_\epsilon}\frac{1}{k^{2+ \beta}} < 1 + \sum_{k=2}^{\infty} \frac{1}{k^{2+ \beta}} < 1+  \int_{1}^{\infty} \frac{1}{x^{2+ \beta}} dx =  \frac{\beta +2}{\beta+1},\nonumber\\
    &\sum_{k=1}^{N_\epsilon}\frac{1}{k^{1+ 0.5\beta}} < 1 + \sum_{k=2}^{\infty} \frac{1}{k^{1+ 0.5\beta}} < 1+  \int_{1}^{\infty} \frac{1}{x^{1+ 0.5\beta}} dx = \frac{\beta + 2}{\beta}.
\end{align*}
Substituting these bounds into the previous inequality \eqref{eq:bound1}, we have
\begin{align*}
\EE [N_G ] 
 &\leq \frac{1}{2\stepsizebar\epsilon} \left [2\|x_0 - x^* \|^2 + \frac{4(\beta + 2)^2}{\beta^2} + \frac{8(\beta+2)}{\beta+1} 
 \right]. 
\end{align*}
which is the statement of Theorem \ref{th:bound_expectation_N_TS1}.
~\qed \end{proof}

We note that the steps 4 and 5 of Algorithm \ref{alg:fista_bktr_line_search} are exactly as Algorithm \ref{alg:ista_bktr_line_search}.
Since the dynamics of the step-size parameter is based on the reference points $y_k$, $\tilde{p}_{\alpha_k} (y_k)$ in Step 4 and the sufficient decrease condition in Step 5, 
the results in Sections \ref{sec:stoc_proc} and \ref{subsec:successful}  hold  for Algorithm \ref{alg:fista_bktr_line_search} under the same assumptions as for 
Algorithm \ref{alg:ista_bktr_line_search}. 


\begin{lemma}\label{lem:fista_linesearch}
 We denote $\alpha^{succ}_k$ be the step-size parameter  at the successful iteration up to iteration $k$: 
\begin{align*}
    \alpha^{succ}_k = \alpha_{k'}, \text{ where } k' = \max \{k'' \text{ successful }, k'' \leq k\} .
\end{align*}
We also adopt the convention that $\alpha^{succ}_k = \alpha_0 = \gamma \alpha_1$ if there is no successful iteration up to iteration $k$. Then we have the following properties:

1. $\alpha^{succ}_{k-1} t_{k-1}^2\geq \alpha_k t_k(t_{k}-1)$ for every successful iteration $k$.

2. $\alpha^{succ}_{K} t_{K}^2 \geq \left(\sum_{k \in S, k \le K } \sqrt{\alpha_k} /2\right)^2$ for any number of iterations $K$.

\end{lemma}

\begin{proof}
1. From the update of the algorithm and the fact that $k$ is successful: 
\begin{align*}
    t_k = t_k^{next} &=  \frac{1 + \sqrt{1+4\theta_{k-1} t_{k-1}^2}}{2},
\end{align*}
we have $ \theta_{k-1} t_{k-1}^2=  t_k(t_{k}-1)$.
The statement of the lemma $\alpha^{succ}_{k-1} t_{k-1}^2\geq \alpha_k t_k(t_{k}-1)$ is equivalent to  
\begin{align*}
\alpha^{succ}_{k-1} \geq \alpha_k \theta_{k-1}.
\end{align*}
Let $k'$ be the previous successful iteration prior to $k$ ($k' < k$), i.e. $\alpha^{succ}_{k-1} = \alpha_{k'}$ and $\alpha^{succ}_{k-1} = \alpha_{0}$ if there is no successful iteration prior to $k$. By the definition of $k'$ we have 
$\alpha_{k'+1} = \tfrac{\alpha_{k'}}{\gamma},$ and $\theta_{k'} = \gamma $.
Since the iterations from $k' + 1$ to $k-1$ are unsuccessful (if $k' <k-1$): 
\begin{align*}
    \alpha_{k} &= \alpha_{k'+1} \cdot  \gamma^{k-k'-1}\nonumber\\
    \theta_{k-1} &= \theta_{k'} \gamma^{k'+1 -k}.
\end{align*}
Therefore 
\begin{align*}
    \alpha_{k} &= \alpha_{k'+1} \cdot  \gamma^{k-k'-1}= \alpha_{k'} \cdot  \gamma^{k-k'-2} \nonumber\\
    \theta_{k-1} &= \theta_{k'} \gamma^{k'+1 -k} = \gamma^{k'+2 -k},
\end{align*}
and it proves the statement: 
    \begin{align}\label{eq:theta}
    \alpha_k \theta_{k-1} = \alpha_{k'} \cdot  \gamma^{k-k'-2} \cdot \gamma^{k'+2 -k} = \alpha_{k'}. 
    \end{align}



% \katya{This proof is critical. Is it actually true for all iterations, including unsuccessful ones?}

% \trang{Actually we need $ \alpha^{succ}_{K} t_{K}^2 \geq \left(\sum_{k \in S, k \le K } \sqrt{\alpha_k} /2\right)^2$ for every $K \leq  N_\epsilon-1$. (I forgot the $^{succ}$ before). Maybe the proof only need $K = N_\epsilon-1$ but this lemma needs to be true for every iteration. We can prove this for all successful iterations, then for unsuccessful one, it still holds since it holds for the prior successful one i.e. no term changes (algo do not update $t_k$). But looking at this, technically $t_k$ do not has at least order $k$ directly, it has the order of the number of good iterations before $k$}


2. First, we prove the statement for all iterations $K$ where $K$ is successful. We prove this by induction. 
\begin{itemize}
\item Let $k_1 \geq 1$ be the first successful iteration of the algorithm. By definition we have 
$\alpha^{succ}_{k_1} = \alpha_{k_1}, \text{ since } k_1 = \max \{k'' \text{ successful }, k'' \leq k_1\} $.  
Since $k_1$ is successful:
\begin{align*}
    t_{k_1} = t_{k_1}^{next} = \frac{1 + \sqrt{1+4\theta_{(k_1-1)} t_{(k_1-1)}^2}}{2}= \frac{1 + \sqrt{1+4\theta_{(k_1-1)} \cdot 0}}{2} = 1.
\end{align*}
Therefore the statement holds for $k_1$: 
\begin{align*}
    \alpha^{succ}_{k_1} t_{k_1}^2 =  \alpha_{k_1} \cdot 1 \geq \left( \sqrt{\alpha_{k_1}} /2\right)^2 = \left(\sum_{k \in S, k \le k_1 } \sqrt{\alpha_k} /2\right)^2.
\end{align*}
\item Now for an iteration $K$ where $K$ is successful, we assume the statement holds for the successful iteration $k'$ prior to $K$ ($k'$ is the largest index of a successful iteration satisfying $k' < K$). We have 
$ \alpha^{succ}_{k'} t_{k'}^2 \geq \left(\sum_{k \in S, k \le k' } \sqrt{\alpha_k} /2\right)^2$ and  
\begin{align*}
    \sqrt{\alpha^{succ}_{k'}} t_{k'} \geq \sum_{k \in S, k \le k' } \sqrt{\alpha_k} /2.
\end{align*}

Since both $K$ and $k'$ are successful, $ \alpha^{succ}_{K} =  \alpha_{K} $ and $ \alpha^{succ}_{k'} =  \alpha_{k'} $.
Using the fact that $K$ is successful: 
\begin{align*}
    t_{K} &= t_{K}^{next} = \frac{1 + \sqrt{1+4\theta_{(K-1)} t_{(K-1)}^2}}{2} \geq \frac{1}{2} +  \sqrt{\theta_{(K-1)}}  t_{(K-1)}\\
    &\geq \frac{1}{2} +  \sqrt{\theta_{(K-1)} } \cdot t_{k'} \geq \frac{1}{2} +  \sqrt{\frac{\alpha_{k'}}{\alpha_{K}} } \cdot t_{k'}.
\end{align*}
where the last inequality follows from previous argument \eqref{eq:theta}.
Hence we have 
\begin{align*}
    \sqrt{\alpha^{succ}_{K}} t_{K} = \sqrt{\alpha_{K}} t_{K} \geq \sqrt{\alpha_{k'}} t_{k'} + \sqrt{\alpha_K} /2 = \sqrt{\alpha^{succ}_{k'}} t_{k'} + \sqrt{\alpha_K} /2.
\end{align*}
Therefore 
\begin{align*}
    \sqrt{\alpha^{succ}_{K}} t_{K} \geq \sum_{k \in S, k \le k' } \sqrt{\alpha_k} /2 + \sqrt{\alpha_K} /2 = \sum_{k \in S, k \le K } \sqrt{\alpha_k} /2,
\end{align*}
and the statement holds for iteration $K$:
$ \alpha^{succ}_{K} t_{K}^2 \geq \left(\sum_{k \in S, k \le K } \sqrt{\alpha_k} /2\right)^2$.
\item By induction, the statement holds for all the successful iterations. For an arbitrary unsuccessful iteration $K$, the statement holds for the successful iteration $k'$ prior to $K$ and neither right hand side  {nor} left hand side term changes at  unsuccessful iteration. The statement is also true in the case when there is no successful iteration prior to $K$ as both sides equal to 0 ($t_0 = 0$). Therefore it holds for every iteration. 
\end{itemize}
% \katya{what is there is no prior successful iteration? Show that is holds for $K=1$}
~\qed \end{proof}

\begin{lemma}[$m_{k}$ on unsuccsessful steps]\label{lem:unsuccessful_step_bound}
Let $m_k$ be defined as in \eqref{eq:define_m}. 
If iteration $k$ of Algorithm \ref{alg:fista_bktr_line_search}  is unsuccessful, then we have 
\begin{align*}m_{k} = m_{k-1}. \end{align*}
\end{lemma}

\begin{lemma}[$m_k$ on  successful step]\label{lem:successful_step_bound}
Under Assumption \ref{assumpt:convex_smooth}, if $k$ is a successful iteration of Algorithm \ref{alg:fista_bktr_line_search}, then we have:
 %\katya{I think here and in ISTA analysis it is best to use $b_k$ instead of $b_k$ for realizations and switch to $b_k$ when taking expectation. }
\begin{align*}
&2\alpha^{succ}_{k}t_k^2 v_k -2\alpha^{succ}_{k-1} t_{k-1}^2v_{k-1} \leq \norm{u_{k-1}}^2 -  \norm{u_k }^2 + \lambda_k \cdot \| u_{k-1}\|,
\end{align*}
where 
\begin{align*}
\lambda_k =  \|2\alpha_kt_k (\nabla f(y_k )- g_k )\|.
\end{align*}
Equivalently, 
\begin{align*}
m_{k} -m_{k-1} \leq \lambda_k \cdot \|u_{k-1}\|.
\end{align*}
\end{lemma}

\begin{proof}
Since $k$ is a successful iteration, we have $F(\tilde{p}_{\alpha_k} (y_k)) \leq \tilde{Q}_{\alpha_k}(\tilde{p}_{\alpha_k} (y_k), y_k)$. 
Also $x_k = \tilde{p}_{\alpha_k} (y_k) $. %; t_k = t_k^{next}$.
Hence 
\begin{align*}
    F(x_k) = f(x_k) + h(x_k) \leq f(y_k) +(x_k -y_k)^\top g_k + \frac{1}{2\alpha_k}\|x_k-y_k\|^2 + h(x_k) .
\end{align*}
By the  convexity of $f$ at $x$ and $y_k$ and the convexity of $h$ at $x$ and $x_k$:
\begin{align*}
f(x) \geq f(y_k) + \nabla f(y_k )^\top (x-y_k),
\nonumber\\
h(x) \geq h(x_k) + \gamma(y_k)^\top (x-x_k),
\end{align*}
where the second bound holds for every subgradient $\gamma(y_k)$ of $h$ at $x_k$. 
We have 
\begin{align*}
F(x) &= f(x) + h(x)\geq f(y_k)+ h(x_k) + \nabla f(y_k )^\top (x-y_k)  + \gamma(y_k)^\top (x-x_k)
\nonumber\\
&= f(x) + h(x)\geq f(y_k)+ h(x_k) + [\nabla f(y_k )+ \gamma(y_k)]^\top (x-y_k)  + \gamma(y_k)^\top ( y_k -x_k) 
\end{align*}
Combine this with the previous bound of $F(x_k)$ we have 
\begin{align*}
&F(x) - F(x_k) \nonumber\\&\geq  [\nabla f(y_k )+ \gamma(y_k)]^\top (x-y_k)  + \gamma(y_k)^\top ( y_k -x_k) - (x_k -y_k)^\top g_k - \frac{1}{2\alpha_k}\|x_k-y_k\|^2\nonumber\\
&=  [\nabla f(y_k )+ \gamma(y_k)]^\top (x-y_k)  + (\gamma(y_k)+g_k)^\top ( y_k -x_k)  - \frac{1}{2\alpha_k}\|x_k-y_k\|^2.
\end{align*}
Using the fact that $x_k = \tilde{p}_{\alpha_k} (y_k) =\arg\min_y \tilde{Q}_{\alpha_k}(y, y_k)$, we get that $ y_k - x_k= \alpha_k[\gamma(y_k)+g_k]$ for some subgradient $\gamma(y_k)$ of $h$ at $x_k$. Therefore
\begin{align*}
F(x) - F(x_k)
&\geq  [\nabla f(y_k )+ \gamma(y_k)]^\top (x-y_k)  + \alpha_k\|\gamma(y_k)+g_k) \|^2 - \frac{1}{2} \alpha_k \|\gamma(y_k)+g_k)\|^2\nonumber\\
&=  [\nabla f(y_k )+ \gamma(y_k)]^\top (x-y_k)  + \frac{\alpha_k}{2}\|\gamma(y_k)+g_k) \|^2 .
\end{align*}
Apply this equation for $x = x_{k-1}$ and $x=x^*$ we have 
\begin{align*}
F(x_{k-1}) - F(x_k) &\geq  [\nabla f(y_k )+ \gamma(y_k)]^\top (x_{k-1}-y_k)  + \frac{\alpha_k}{2}\|\gamma(y_k)+g_k) \|^2 ,
\nonumber\\
F(x^*) - F(x_k) &\geq  [\nabla f(y_k )+ \gamma(y_k)]^\top (x^*-y_k)   + \frac{\alpha_k}{2}\|\gamma(y_k)+g_k) \|^2 .
\end{align*}
Let $v_k =  F(x_k) - F(x^*) $ then 
\begin{align*}
v_{k-1} - v_k &\geq  [\nabla f(y_k )+ \gamma(y_k)]^\top (x_{k-1}-y_k)  + \frac{\alpha_k}{2}\|\gamma(y_k)+g_k) \|^2  ,
\nonumber\\
-v_k &\geq  [\nabla f(y_k )+ \gamma(y_k)]^\top (x^*-y_k)   + \frac{\alpha_k}{2}\|\gamma(y_k)+g_k) \|^2  .
\end{align*}
Multiplying the first equality by $t_{k}-1$ and adding to the second equality, we get
\begin{align*}
(t_{k}-1)v_{k-1} - t_k v_k &\geq  [\nabla f(y_k )+ \gamma(y_k)]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k )   + \frac{\alpha_k}{2} t_k \|\gamma(y_k)+g_k) \|^2 .
\end{align*}
Multiplying the previous inequality by $t_k$ we have
 \begin{align*}
 &t_k(t_{k}-1)v_{k-1} - t_k^2 v_k \nonumber\\
 &\geq t_k [\nabla f(y_k )+ \gamma(y_k)]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k )   + \frac{\alpha_k}{2}t_k^2\|\gamma(y_k)+g_k) \|^2 \nonumber\\
&=  t_k [\nabla f(y_k )- g_k +g_k + \gamma(y_k)]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k )  + \frac{\alpha_k}{2}t_k^2\|\gamma(y_k)+g_k) \|^2
\nonumber\\
&=  t_k [g_k + \gamma(y_k)]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k )  + \frac{\alpha_k}{2}t_k^2\|\gamma(y_k)+g_k) \|^2
 \nonumber\\&
+ t_k [\nabla f(y_k )- g_k ]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k ) 
\nonumber\\
&=  t_k \frac{1}{\alpha_k}(y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k )  + \frac{\alpha_k}{2}t_k^2\|\gamma(y_k)+g_k) \|^2
 \nonumber\\&
+ t_k [\nabla f(y_k )- g_k ]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k ) 
\nonumber\\
&=  t_k 
\frac{1}{\alpha_k}(y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k x_k )   + t_k 
\frac{1}{\alpha_k}(y_k - x_k)^\top t_k(x_k -y_k)  \nonumber\\&
+ \frac{1}{2\alpha_k}t_k^2\|x_k -y_k \|^2
+ t_k [\nabla f(y_k )- g_k ]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k ) 
\nonumber\\
&=  t_k 
\frac{1}{\alpha_k}(y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k x_k )   -  
\frac{1}{2\alpha_k}\norm{t_k (x_k -y_k)}^2 \nonumber\\&
+ t_k [\nabla f(y_k )- g_k ]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k ) .
\end{align*}
Multiplying the final statement by $2\alpha_k $ we get 
 \begin{align}\label{eq_bound_mu_t}
&~2\alpha_k t_k(t_{k}-1)v_{k-1} - 2\alpha_kt_k^2 v_k \nonumber\\
&\geq 2t_k 
(y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k x_k )   -  
\norm{t_k (x_k -y_k)}^2  \nonumber\\
&  + 2\alpha_kt_k [\nabla f(y_k )- g_k ]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k ) .
\end{align}
Now we consider the following term: $2t_k 
(y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k x_k )   -  
\norm{t_k (x_k -y_k)}^2$.
% \begin{align*}
% 2t_k 
% (y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k x_k )   -  
% \norm{t_k (x_k -y_k)}^2.
% \end{align*}
Let $a  = t_k 
(y_k - x_k), b = (t_{k}-1)x_{k-1} + x^* - t_k x_k$ we have 
\begin{align}\label{eq:03}
    & \quad \ 2t_k 
(y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k x_k )   -  
\norm{t_k (x_k -y_k)}^2\nonumber\\ &=  2ab - a^2 \nonumber\\
&= b^2 -b^2 +2ab - a^2= b^2 -(a-b)^2\nonumber\\
&=\norm{(t_{k}-1)x_{k-1} + x^* - t_k x_k }^2 -\norm{(t_{k}-1)x_{k-1} + x^* - t_k x_k  -t_k (y_k - x_k)}^2\nonumber\\
&=\norm{(t_{k}-1)x_{k-1} + x^* - t_k x_k }^2 -\norm{(t_{k}-1)x_{k-1} + x^* - t_k y_k  }^2.
\end{align}
Since $k$ is a successful iteration, we have that $x^{prev}_{k} = x_{k-1}$. From the definition of $u_k$
\begin{align*}u_k = (t_{k}-1)x^{prev}_{k} + x^* - t_k x_k, \end{align*} 
we have that 
\begin{align*}u_k = (t_{k}-1)x_{k-1} + x^* - t_k x_k. \end{align*} 
Now from the definition of FISTAStep \eqref{eq:fista_step}
\begin{align*}y_k = x_{k-1} + \frac{t_{k-1}-1}{t_{k}} ( x_{k-1} - x^{prev}_{k-1} ),\end{align*}
we have 
\begin{align*}t_k y_k = t_kx_{k-1} + (t_{k-1}-1) ( x_{k-1} - x^{prev}_{k-1} ).\end{align*}
Combining these equations with \eqref{eq:03} we get: 
\begin{align*}
& \quad \ 2t_k 
(y_k - x_k)^\top ((t_{k}-1)x_{k-1} + x^* - t_k x_k )   -  
\norm{t_k (x_k -y_k)}^2\nonumber\\
&=\norm{(t_{k}-1)x_{k-1} + x^* - t_k x_k }^2 -\norm{(t_{k}-1)x_{k-1} + x^* - t_k y_k  }^2\nonumber\\
&=\norm{u_k }^2 -\norm{(t_{k}-1)x_{k-1} + x^* - t_kx_{k-1} - (t_{k-1}-1) ( x_{k-1} -  x^{prev}_{k-1} )  }^2\nonumber\\
&=\norm{u_k }^2 -\norm{-t_{k-1} x_{k-1} + x^*  + (t_{k-1}-1)  x^{prev}_{k-1}  }^2\nonumber\\
&=\norm{u_k }^2 -\norm{-u_{k-1}}^2.
\end{align*}
Substituting back to previous equality \eqref{eq_bound_mu_t} we get 
 \begin{align*}
&2\alpha_k t_k(t_{k}-1)v_{k-1} - 2\alpha_kt_k^2 v_k \nonumber\\
&\geq \norm{u_k }^2 -\norm{u_{k-1}}^2  + 2\alpha_kt_k [\nabla f(y_k )- g_k ]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k ) .
\end{align*}
Therefore  
  \begin{align*}
&2\alpha_kt_k^2 v_k -2\alpha_k t_k(t_{k}-1)v_{k-1}\nonumber\\ % &\leq \norm{u_{k-1}}^2 -  \norm{u_k }^2 -2\alpha_kt_k [\nabla f(y_k )- g_k ]^\top ((t_{k}-1)x_{k-1} + x^* - t_k y_k ) \nonumber\\
&\leq \norm{u_{k-1}}^2 -  \norm{u_k }^2 + \|2\alpha_kt_k (\nabla f(y_k )- g_k )\| \cdot \| u_{k-1}\|.
\end{align*}
From Lemma \ref{lem:fista_linesearch} we have $\alpha^{succ}_{k-1} t_{k-1}^2\geq \alpha_k t_k(t_{k}-1)$
for every successful iteration $k$. Also since $k$ is successful, we have  $\alpha_k = \alpha^{succ}_{k}$.
Therefore we have the final bound of Lemma \ref{lem:successful_step_bound}.
~\qed \end{proof}

\begin{lemma}\label{lem:after_K}
Given any integer $K$, after $K$ iterations of the algorithm, the following bound holds: 
\begin{align*}
    2\alpha^{succ}_{K} t_{K}^2v_{K} \leq 3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \sum_{k=1}^{K} \lambda_{k} \cdot \left[\sum_{i=1}^{k-1} \lambda_{i} \right]  + 2\sum_{k=1}^{K} \lambda_{k} ^2  .
\end{align*}
\end{lemma}

\begin{proof}
For every $K$, from Lemma \ref{lem:unsuccessful_step_bound}  we have
\begin{align*}
    m_K - m_0 = \sum_{k \in S, k\leq K} (m_{k} -m_{k-1}),
\end{align*}
where $S$ is the set of successful iterations.
We apply Lemma \ref{lem:successful_step_bound} for successful iterations and then 
\begin{align*}
    m_K - m_0 &= \sum_{k \in S, k\leq K} (m_{k} -m_{k-1})\leq \sum_{k \in S, k\leq K} \lambda_k \cdot \|u_{k-1}\| \leq \sum_{k=1}^{K} \lambda_k \cdot \| u_{k-1}  \|  .
\end{align*}
Plugging this and the definition of $m_k$ back to the previous inequality, we have our key bound: 
\begin{align}\label{eq:thm_key}
    2\alpha^{succ}_{K} t_{K}^2v_{K} +\norm{u_K }^2 
    &\leq \left(2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2\right) + \sum_{k=1}^{K} \lambda_k \cdot \| u_{k-1}\| .
\end{align}
Similar to the proof of ISTA, 
we follow the argument in \cite{Schmidt-Roux-Bach} with two steps. First, we use the key bound \eqref{eq:thm_key} to bound $\| u_{k-1}\|$ in terms of the noise terms $\lambda_k$. Then we use this bound on $\| u_{k-1}\|$ to substitute into the last sum of the key bound \eqref{eq:thm_key} and obtain the final derivation in terms of the noise $\lambda_k$.
Ignoring the positive term $2\alpha^{succ}_{K} t_{K}^2v_{K}$, we have 
\begin{align*}
    \norm{u_K }^2 
    &\leq \left(2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2\right) + \sum_{k=1}^K \lambda_k \cdot \| u_{k-1}\| \nonumber\\
    &= 2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \lambda_1 \cdot \| u_{0}\| + \sum_{k=1}^{K} \lambda_{k+1} \cdot \| u_{k}\|.
\end{align*}
This is equivalent to 
\begin{align*}
    \norm{u_K }^2 
    \leq Z + \sum_{k=1}^{K} \lambda_{k+1} \| u_{k}\|,
\end{align*}
where $Z = 2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \lambda_1 \| u_{0}\|$.
Using this inequality and applying Lemma 1 in \cite{Schmidt-Roux-Bach} for the non-negative sequence $\{\|u_K\|\}$, we have
\allowdisplaybreaks
\begin{align*}
    \| u_{k}\| &\leq \frac{1}{2} \sum_{i=1}^{k} \lambda_{i+1} + \left( Z + \left(\frac{1}{2} \sum_{i=1}^{k} \lambda_{i+1} \right)^2\right)^{1/2}
    \leq  \sum_{i=1}^{k} \lambda_{i+1} +  Z^{1/2} \nonumber\\
    &\leq  \sum_{i=1}^{k+1} \lambda_{i} + \left(2\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2  \right)^{1/2},
\end{align*}
where the last line follows from the fact that
\begin{align*}
    Z^{1/2} &= \sqrt{2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \lambda_1 \| u_{0}\|  } \leq  \sqrt{2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \lambda_1^2 +\| u_{0}\|^2  } \nonumber\\
    &\leq \sqrt{2\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \lambda_1^2  } \leq  \lambda_1 + \left(2\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2  \right)^{1/2}.
\end{align*}
Dropping the term $\norm{u_K }^2 $ in 
the inequality \eqref{eq:thm_key} and using the bound on $\| u_{k}\|$ we have: 
\allowdisplaybreaks
\begin{align*}
    &2\alpha^{succ}_{K} t_{K}^2v_{K} \nonumber\\
    &\leq 2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \sum_{k=1}^{K} \lambda_{k} \cdot \| u_{k-1}\| \nonumber\\
    &\leq 2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \sum_{k=1}^{K} \lambda_{k} \cdot \left[\sum_{i=1}^{k} \lambda_{i} + \left(2\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2  \right)^{1/2} \right] \nonumber\\
    &= 2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \sum_{k=1}^{K} \lambda_{k} \cdot \left[\sum_{i=1}^{k} \lambda_{i} \right] + \left(2\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2  \right)^{1/2} \sum_{k=1}^{K} \lambda_{k}   \nonumber\\
    &\leq 2\alpha^{succ}_{0} t_{0}^2v_{0} +\norm{u_0 }^2 + \sum_{k=1}^{K} \lambda_{k} \cdot \left[\sum_{i=1}^{k-1} \lambda_{i} \right]  + \sum_{k=1}^{K} \lambda_{k} ^2+  \frac{1}{2} \left(2\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2  \right)  + \sum_{k=1}^{K} \lambda_{k} ^2\nonumber\\
    &= 3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \sum_{k=1}^{K} \lambda_{k} \cdot \left[\sum_{i=1}^{k-1} \lambda_{i} \right]  + 2\sum_{k=1}^{K} \lambda_{k} ^2,  
\end{align*}
which is our desired bound. 
~\qed 
\end{proof}

\begin{theorem}[Upper bound of the number of large true successful steps]\label{th:bound_expectation_N_TS}
Under Assumptions \ref{assumpt:convex_smooth}, \ref{assumpt:bounded_below}
and  \ref{assumpt:fista_noise}, we have  
 \begin{align*}
 \EE [N_G] \leq \sqrt{
 \frac{2}{\stepsizebar\epsilon} \left [3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \frac{4(\beta + 2)^2}{\beta^2} + \frac{8(\beta+2)}{\beta+1}  
 \right] }. 
\end{align*}

\end{theorem}

\begin{proof} 
Since the statement of Lemma \ref{lem:after_K} holds for every realizations of Algorithm \ref{alg:fista_bktr_line_search}, for $K = N_\epsilon -1$ we have: 
\begin{align*}
    2\Alpha^{succ}_{N_\epsilon -1} T_{N_\epsilon -1}^2 (F(X_{N_\epsilon -1}) - F^*)\leq 3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \sum_{k=1}^{N_\epsilon -1} \Lambda_{k} \cdot \left[\sum_{i=1}^{k-1} \Lambda_{i} \right]  + 2\sum_{k=1}^{N_\epsilon -1} \Lambda_{k} ^2.
\end{align*}
Recall that $N_\epsilon$ be the stopping time that $N_\epsilon = \inf\{k: F(X_k) - F^* \leq \epsilon\}$. Hence for $K = N_\epsilon -1$, we have that $F(X_K) - F^* > \epsilon$ and 
\begin{align*}
    2\Alpha^{succ}_{N_\epsilon -1} T_{N_\epsilon -1}^2 &\leq \frac{3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \sum_{k=1}^{N_\epsilon -1} \Lambda_{k} \cdot \left[\sum_{i=1}^{k-1} \Lambda_{i} \right]  + 2\sum_{k=1}^{N_\epsilon -1} \Lambda_{k}^2}{F(X_{N_\epsilon -1}) - F^*} \nonumber\\
    &\leq \frac{3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \sum_{k=1}^{N_\epsilon} \Lambda_{k} \cdot \left[\sum_{i=1}^{k-1} \Lambda_{i} \right]  + 2\sum_{k=1}^{N_\epsilon} \Lambda_{k} ^2}{\epsilon}.
\end{align*}
Let $\mathcal{N}_G$ be the set of \textit{good} iterations  (i.e. true and successful iterations $k$ with $\alpha_k\geq \stepsizebar $), with $ k \leq N_\epsilon -1$, then $N_G$ is the cardinality of that set. 
Using the inequality $ \alpha^{succ}_{K} t_{K}^2 \geq \left(\sum_{k \in S, k \le K } \sqrt{\alpha_k} /2\right)^2$ for $K =  N_\epsilon-1$ from Lemma \ref{lem:fista_linesearch} we have 
\begin{align*} 
\Alpha^{succ}_{N_\epsilon -1} T_{N_\epsilon -1}^2 
&\geq \left(\sum_{k \in S, k \le N_\epsilon -1} \sqrt{\Alpha_k} /2\right)^2 \nonumber\\
&\geq \left(\sum_{k\in \mathcal{N}_G, k \le N_\epsilon -1 } \sqrt{\Alpha_k} /2\right)^2
\geq \left(N_G \sqrt{\stepsizebar} /2\right)^2 
= \frac{1}{4} (N_G)^2 \stepsizebar.
\end{align*}
Substituting this to the previous inequality we get 
 \begin{align*}
(N_G)^2  &\leq  \frac{2}{\stepsizebar\epsilon} \left [3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \sum_{k=1}^{N_\epsilon} \Lambda_{k} \cdot \left[\sum_{i=1}^{k-1} \Lambda_{i} \right]  + 2\sum_{k=1}^{N_\epsilon} \Lambda_{k} ^2   \right].
\end{align*}
Taking total expectation we have: 
\begin{align*}
\EE [(N_G)^2 ]   &\leq \frac{2}{\stepsizebar\epsilon} \left [3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 
+ \EE \left[ \sum_{k=1}^{N_\epsilon } \Lambda_{k} \cdot \left(\sum_{i=1}^{k-1} \Lambda_{i} \right)  \right] + 2\EE \left[\sum_{k=1}^{N_\epsilon }  \Lambda_{k} ^2  \right] 
 \right].
\end{align*}
From \eqref{eq:fista_noise} we have: 
\begin{align*}
    \EE \left[\Lambda_{k}^2| \pastone\right] = \EE \left[4\alpha_{k}^2t_k^2 \| (\nabla f(y_{k} )- G_{k} )\|^2 | \pastone\right] \leq \frac{4}{k^{2+ \beta}},
\end{align*}
Hence using a similar argument as Theorem \ref{th:bound_expectation_N_TS1} we get 
\begin{align*}
\EE [(N_G)^2 ]
 &\leq \frac{2}{\stepsizebar\epsilon} \left [3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2  + \frac{4(\beta + 2)^2}{\beta^2} + \frac{8(\beta+2)}{\beta+1} 
 \right].
\end{align*}
By the expectation inequality: 
 \begin{align*}
\EE [N_G] \leq \sqrt{
 \frac{2}{\stepsizebar\epsilon} \left [3\alpha^{succ}_{0} t_{0}^2v_{0} +2\norm{u_0 }^2 + \frac{4(\beta + 2)^2}{\beta^2} + \frac{8(\beta+2)}{\beta+1}  
 \right] }.
\end{align*}
we get the final results of Theorem \ref{th:bound_expectation_N_TS}. 
~\qed \end{proof}

Our final result is a straightforward corollary of Theorem \ref{th:framework} and \ref{th:bound_expectation_N_TS}.

