\begin{lemma}[Bounds for a successful step]\label{lem:successful_step_bound1}
If $k$ is a successful iteration then we have:
\begin{align*}
\|x_{k} - x^*\|^2 - \|x_{k-1} - x^* \|^2 \leq  - 2\alpha_k (F(x_k) - F(x^*) )  + \lambda_k \cdot \|x_{k-1} -x^*\|,
\end{align*}
where $\lambda_k = \| 2\alpha_k (\nabla f(x_{k-1})-g_k) \| $.
\end{lemma}

\begin{proof}
Since iteration $k$ is successful,  the sufficient decrease condition holds: 
\begin{align*}
    F(\tilde{p}_{\alpha_k} (x_{k-1})) &\leq \tilde{Q}_{\alpha_k}(\tilde{p}_{\alpha_k} (x_{k-1}), x_{k-1}) \nonumber\\
    &= f(x_{k-1}) +(x_k -x_{k-1})^\top g_k + \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2 + h(x_k).
\end{align*}
By the  convexity of $f$ and $h$, applied at $x_{k-1}$ and $x_k$ respectively, for any $x$,  
 \begin{align*}
f(x) &\geq f(x_{k-1}) + \nabla f(x_{k-1})^\top (x-x_{k-1}),
\nonumber\\
h(x) &\geq h(x_k) + \gamma(x_{k-1})^\top (x-x_k),
\end{align*}
where the second bound holds for every subgradient $\gamma(x_{k-1})$ of $h$ at $x_{k}$. 
Summing those inequality we have 
\begin{align*}
f(x) +h(x) \geq f(x_{k-1}) + \nabla f(x_{k-1})^\top (x-x_{k-1})+ h(x_k) + \gamma(x_{k-1})^\top (x-x_k).
\end{align*}
Combining this with the sufficient decrease condition we get: 
\begin{align*}
    &F(x) - F(x_k) \nonumber\\&\geq \nabla f(x_{k-1})^\top (x-x_{k-1}) + \gamma(x_{k-1})^\top (x-x_k) - (x_k -x_{k-1})^\top g_k - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + (\gamma(x_{k-1})+g_k)^\top (x-x_k) - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2.
\end{align*}
Using the fact that $x_k = \tilde{p}_{\alpha_k} (x_{k-1}) =\arg\min_x \tilde{Q}_{\alpha_k}(x, x_{k-1})$, we get that $ x_{k-1} - x_k= \alpha_k[\gamma(x_{k-1})+g_k]$ for some subgradient $\gamma(x_{k-1})$ of $h$ at $x_{k}$. Therefore
\begin{align*}
    &F(x) - F(x_k) \nonumber\\
    &\geq (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{\alpha_k}(x_{k-1} - x_k)^\top (x-x_k) - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{\alpha_k}(x_{k-1} - x_k)^\top (x-x_{k-1} + x_{k-1} -x_k) \nonumber\\
    & \quad - \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{\alpha_k}(x_{k-1} - x_k)^\top (x-x_{k-1}) + \frac{1}{2\alpha_k}\|x_k-x_{k-1}\|^2\nonumber\\
    &= (\nabla f(x_{k-1})-g_k) ^\top (x-x_{k-1}) + \frac{1}{2\alpha_k} \left( \|x-x_k \|^2-\|x-x_{k-1} \|^2\right),
\end{align*}
and we get the bound for $x=x^*$: 
\begin{align*}
    &2\alpha_k (F(x_k) - F(x^*) ) - 2\alpha_k (\nabla f(x_{k-1})-g_k) ^\top (x_{k-1} -x^*)
    \leq \|x_{k-1} - x^*\|^2 - \|x_k - x^* \|^2.
\end{align*}
Rearranging the terms, we get the statement of Lemma \ref{lem:successful_step_bound1}:
\begin{align*}
    \|x_k - x^* \|^2 - \|x_{k-1} - x^*\|^2 &\leq -2\alpha_k (F(x_k) - F(x^*) ) + 2\alpha_k (\nabla f(x_{k-1})-g_k) ^\top (x_{k-1} -x^*)\nonumber\\
    &\leq -2\alpha_k (F(x_k) - F(x^*) ) + \lambda_k \cdot\|x_{k-1} -x^*\|,
\end{align*}
where $\lambda_k = \|2\alpha_k (\nabla f(x_{k-1})-g_k)\|$.

~\qed \end{proof}

